def _assert_valid_test_case(test_case, expected_keys=None):
    """Validate the structural contract of a generated test case."""
    assert isinstance(test_case, dict), "Test case must be a dict"
    expected_keys = expected_keys or {"name", "args", "expected"}
    assert expected_keys.issubset(test_case.keys()), (
        f"Missing keys: {expected_keys - test_case.keys()}"
    )
    assert isinstance(test_case["name"], str) and test_case["name"], "Name must be non-empty string"
    assert isinstance(test_case["args"], (list, tuple)), "Args must be list or tuple"
    assert "expected" in test_case, "Expected value must be present"


