class TestRobustnessAndPerformance:
    """Validates edge cases, concurrency safety, and performance ceilings."""

    def test_generate_with_none_metadata(self, boundary_strategy):
        """None metadata raises StrategyError."""
        with pytest.raises(StrategyError):
            boundary_strategy.generate(None)

    def test_generate_with_none_metadata_logic(self, logic_branch_strategy):
        """None metadata raises StrategyError."""
        with pytest.raises(StrategyError):
            logic_branch_strategy.generate(None)

    def test_generate_with_metadata_missing_returns(self, boundary_strategy):
        """Missing returns field is tolerated (defaults to None)."""
        metadata = SimpleNamespace(name="f", args=["x"], branches=1)
        result = boundary_strategy.generate(metadata)
        assert len(result) > 0

    def test_generate_with_duplicate_args(self, boundary_strategy):
        """Duplicate args are handled gracefully."""
        metadata = SimpleNamespace(name="f", args=["x", "x"], returns="int", branches=1)
        result = boundary_strategy.generate(metadata)
        assert len(result) > 0

    def test_generate_with_special_characters_in_name(self, boundary_strategy):
        """Function names with special characters are preserved."""
        metadata = SimpleNamespace(name="my_func_123", args=["x"], returns="int", branches=1)
        result = boundary_strategy.generate(metadata)
        assert result[0]["name"] == "my_func_123"

    def test_concurrent_generation_safety(self, boundary_strategy, sample_metadata):
        """Concurrent generate() calls produce consistent results."""
        results = []
        errors = []

        def worker():
            try:
                for _ in range(20):
                    results.append(boundary_strategy.generate(sample_metadata))
            except Exception as e:  # pragma: no cover
                errors.append(e)

        threads = [threading.Thread(target=worker) for _ in range(8)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert not errors, f"Concurrent generation failed: {errors}"
        assert len(results) == 160
        # All results must be identical
        assert all(r == results[0] for r in results)

    def test_performance_ceiling(self, boundary_strategy, sample_metadata):
        """Generation completes within a reasonable time budget."""
        start = time.perf_counter()
        for _ in range(100):
            boundary_strategy.generate(sample_metadata)
        elapsed = time.perf_counter() - start
        assert elapsed < 5.0, f"Generation too slow: {elapsed:.2f}s for 100 iterations"

    def test_performance_ceiling_logic(self, logic_branch_strategy, sample_metadata):
        """Logic branch generation completes within a reasonable time budget."""
        start = time.perf_counter()
        for _ in range(50):
            logic_branch_strategy.generate(sample_metadata)
        elapsed = time.perf_counter() - start
        assert elapsed < 5.0, f"Logic branch generation too slow: {elapsed:.2f}s for 50 iterations"

    def test_large_metadata_performance(self, boundary_strategy):
        """Large metadata (many args) still generates quickly."""
        large_metadata = SimpleNamespace(
            name="large_func",
            args=[f"arg_{i}" for i in range(50)],
            returns="int",
            branches=10,
        )
        start = time.perf_counter()
        result = boundary_strategy.generate(large_metadata)
        elapsed = time.perf_counter() - start
        assert len(result) > 0
        assert elapsed < 2.0, f"Large metadata generation too slow: {elapsed:.2f}s"

    def test_extreme_value_handling(self, boundary_strategy):
        """Extreme numeric values are handled without overflow errors."""
        metadata = SimpleNamespace(
            name="extreme_func",
            args=["x"],
            returns="int",
            branches=1,
        )
        with patch.object(
            boundary_strategy,
            "_generate_boundary_values",
            return_value=[10**18, -(10**18), 0],
        ):
            result = boundary_strategy.generate(metadata)
            assert len(result) == 3

    def test_unicode_and_binary_args(self, boundary_strategy):
        """Unicode and binary args are handled."""
        metadata = SimpleNamespace(
            name="unicode_func",
            args=["text", "data"],
            returns="str",
            branches=1,
        )
        result = boundary_strategy.generate(metadata)
        assert len(result) > 0
        # Verify unicode string boundary exists
        text_values = []
        for test_case in result:
            for arg in test_case["args"]:
                if arg[0] == "text":
                    text_values.append(arg[1])
        assert any(isinstance(v, str) and len(v) > 100 for v in text_values)

    def test_nested_data_structures(self, boundary_strategy):
        """Nested lists/dicts are handled without recursion errors."""
        metadata = SimpleNamespace(
            name="nested_func",
            args=["matrix", "config"],
            returns="int",
            branches=1,
        )
        result = boundary_strategy.generate(metadata)
        assert len(result) > 0


