class TestPropertyBased:
    """Property-based validation using Hypothesis for broader coverage."""

    def test_generate_always_returns_valid_structure(self, boundary_strategy):
        """For any valid metadata, generate() returns well-formed test cases."""
        from hypothesis import given, settings, strategies as st

        @given(
            name=st.text(min_size=1, max_size=50),
            args=st.lists(st.text(min_size=1, max_size=20), min_size=0, max_size=10),
            branches=st.integers(min_value=0, max_value=100),
        )
        @settings(max_examples=50)
        def _check(name, args, branches):
            metadata = SimpleNamespace(name=name, args=args, returns="int", branches=branches)
            result = boundary_strategy.generate(metadata)
            assert isinstance(result, list)
            for test_case in result:
                _assert_valid_test_case(test_case)

        _check()

    def test_generate_deterministic_property(self, boundary_strategy):
        """Determinism holds across a range of inputs."""
        from hypothesis import given, settings, strategies as st

        @given(
            name=st.text(min_size=1, max_size=30),
            args=st.lists(st.text(min_size=1, max_size=10), min_size=0, max_size=5),
            branches=st.integers(min_value=0, max_value=20),
        )
        @settings(max_examples=30)
        def _check(name, args, branches):
            metadata = SimpleNamespace(name=name, args=args, returns="int", branches=branches)
            result1 = boundary_strategy.generate(metadata)
            result2 = boundary_strategy.generate(metadata)
            assert result1 == result2

        _check()

    def test_logic_branch_respects_branch_count_property(self, logic_branch_strategy):
        """Generated cases never exceed a reasonable multiple of branch count."""
        from hypothesis import given, settings, strategies as st

        @given(branches=st.integers(min_value=1, max_value=50))
        @settings(max_examples=30)
        def _check(branches):
            metadata = SimpleNamespace(
                name="prop_func", args=["x"], returns="int", branches=branches
            )
            result = logic_branch_strategy.generate(metadata)
            assert len(result) <= branches * 3 + 10

        _check()


