class TestIntegration:
    """Validates strategies work together in a pipeline."""

    def test_boundary_then_logic_pipeline(self, boundary_strategy, logic_branch_strategy, sample_metadata):
        """Boundary and logic strategies can be chained."""
        boundary_cases = boundary_strategy.generate(sample_metadata)
        logic_cases = logic_branch_strategy.generate(sample_metadata)
        combined = boundary_cases + logic_cases
        assert len(combined) > len(boundary_cases)
        assert len(combined) > len(logic_cases)

    def test_strategies_share_metadata_contract(self, boundary_strategy, logic_branch_strategy, sample_metadata):
        """Both strategies accept the same metadata format."""
        assert boundary_strategy.validate_metadata(sample_metadata)
        assert logic_branch_strategy.validate_metadata(sample_metadata)

    def test_generated_cases_are_executable(self, boundary_strategy, sample_metadata):
        """Generated test cases can be executed as Python code."""
        result = boundary_strategy.generate(sample_metadata)
        for test_case in result:
            # Simulate execution of the test case
            exec_globals = {}
            exec(
                f"def {test_case['name']}(*args): return args",
                exec_globals,
            )
            func = exec_globals[test_case["name"]]
            # Extract positional args
            args = [arg[1] for arg in test_case["args"]]
            output = func(*args)
            assert output is not None

    def test_strategy_registry_consistency(self):
        """All strategies expose consistent interfaces."""
        strategies = [BoundaryStrategy(), LogicBranchStrategy()]
        for strategy in strategies:
            assert hasattr(strategy, "generate")
            assert hasattr(strategy, "validate_metadata")
            assert callable(strategy.generate)
            assert callable(strategy.validate_metadata)